BEGIN;
CREATE TABLE tenants(id text PRIMARY KEY,slug text UNIQUE NOT NULL,name text NOT NULL,plan text NOT NULL CHECK(plan IN('free','starter','pro')),monthly_run_limit integer NOT NULL CHECK(monthly_run_limit BETWEEN 1 AND 100000),used_runs integer NOT NULL DEFAULT 0 CHECK(used_runs>=0),status text NOT NULL CHECK(status IN('active','suspended','closed')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(tenant_id text NOT NULL REFERENCES tenants(id),user_id text NOT NULL,role text NOT NULL CHECK(role IN('owner','admin','operator','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE api_keys(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),actor_id text NOT NULL,key_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE workflow_runs(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),workflow_id text NOT NULL,idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN('queued','retry_scheduled','succeeded','dead_lettered')),attempt integer NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 3),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,id));
CREATE TABLE usage_ledger(id bigserial PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),run_id text NOT NULL,event_type text NOT NULL,units integer NOT NULL CHECK(units>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),event_type text NOT NULL,payload jsonb NOT NULL,actor_id text NOT NULL,event_time timestamptz NOT NULL,previous_hash text NOT NULL,event_hash text NOT NULL,PRIMARY KEY(tenant_id,id));
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;ALTER TABLE memberships FORCE ROW LEVEL SECURITY;ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;ALTER TABLE api_keys FORCE ROW LEVEL SECURITY;ALTER TABLE workflow_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE workflow_runs FORCE ROW LEVEL SECURITY;ALTER TABLE usage_ledger ENABLE ROW LEVEL SECURITY;ALTER TABLE usage_ledger FORCE ROW LEVEL SECURITY;ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;ALTER TABLE audit_events FORCE ROW LEVEL SECURITY;
CREATE POLICY memberships_tenant ON memberships USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY keys_tenant ON api_keys USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY runs_tenant ON workflow_runs USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY usage_tenant ON usage_ledger USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY audit_tenant ON audit_events USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
COMMIT;
